const u = $('Telegram Trigger').first().json;
let chat_id, from = {}, text = '', cb = '', cb_id = '', message_id = null;
if (u.callback_query) {
  const q = u.callback_query;
  chat_id = q.message.chat.id; from = q.from || {}; cb = q.data || ''; cb_id = q.id; message_id = q.message.message_id;
} else if (u.message && u.message.chat) {
  chat_id = u.message.chat.id; from = u.message.from || {}; text = (u.message.text || '').trim();
} else { return []; }
const pad = n => String(n).padStart(3, '0');
let action = 'help', arg = '';
if (cb) {
  if (cb === 'home') action = 'home';
  else if (cb === 'help') action = 'help';
  else if (cb === 'set') action = 'settings';
  else if (cb.startsWith('menu:')) { action = 'menu'; arg = parseInt(cb.split(':')[1]) || 0; }
  else if (cb.startsWith('cat:')) { action = 'items'; arg = 'C' + pad(parseInt(cb.split(':')[1])); }
  else if (cb.startsWith('tm:')) { action = 'timepick'; arg = cb.split(':')[1]; }
  else if (cb.startsWith('st:')) { action = 'settime'; arg = cb.split(':').slice(1).join(':'); }
  else if (cb.startsWith('tg:')) { action = 'toggle'; arg = cb.split(':')[1]; }
} else {
  const cmd = text.split(/[ @]/)[0].toLowerCase();
  if (cmd === '/start' || text === 'تسجيل دخول') action = 'start';
  else if (text === 'تسجيل خروج' || cmd === '/stop') { action = 'toggle'; arg = 'off'; }
  else if (cmd === '/menu' || text === 'الأذكار' || text === 'عرض الأذكار') { action = 'menu'; arg = 0; }
  else if (cmd === '/settings' || text === 'الإعدادات') action = 'settings';
  else if (cmd === '/home') action = 'home';
  else if (/^c\d{3}(-\d+)?$/i.test(text)) { action = 'items'; arg = text.toUpperCase(); }
}
return [{ json: { chat_id, first_name: from.first_name || '', username: from.username || '', action, arg, is_cb: !!cb, cb_id, message_id, text } }];

