parameters.query:
SELECT i.code AS item_code, i.text_ar, i.repeat_count
FROM athkar_items i JOIN athkar_categories c ON c.id = i.category_id
WHERE c.slug = 'morning_evening' ORDER BY i.position;

parameters.jsCode:
const users = $('Get Due Users').all().map(i => i.json).filter(u => u.user_id);
const items = $input.all().map(i => i.json).filter(r => r.item_code);
if (!users.length || !items.length) return [];
const LIMIT = 3500;
const mk = slot => {
  const blocks = [slot === 'morning' ? '🌅 أذكار الصباح' : '🌙 أذكار المساء'];
  for (const r of items) {
    const rep = Number(r.repeat_count) > 1 ? `\n(يُكرَّر ${r.repeat_count} مرات)` : '';
    let t = `【${r.item_code}】\n${r.text_ar}${rep}`;
    while (t.length > LIMIT) { blocks.push(t.slice(0, LIMIT)); t = t.slice(LIMIT); }
    blocks.push(t);
  }
  const chunks = []; let cur = '';
  for (const b of blocks) {
    if (cur && (cur.length + b.length + 2) > LIMIT) { chunks.push(cur); cur = b; }
    else cur = cur ? cur + '\n\n' + b : b;
  }
  if (cur) chunks.push(cur);
  return chunks;
};
const cache = {};
const out = [];
for (const u of users) {
  cache[u.slot] = cache[u.slot] || mk(u.slot);
  const ch = cache[u.slot];
  ch.forEach((text, i) => out.push({ json: { user_id: u.user_id, category_id: u.category_id, slot: u.slot, chat_id: u.telegram_id, text, last: i === ch.length - 1 } }));
}
return out;
